    {"name": "The WARN is real, not a checker artefact", "input": "echo '{\"tool_name\":\"Bash\",\"agent_type\":\"sre\",\"tool_input\":{\"command\":\"cd /home/user/frappe-bench && bench --site test.localhost run-tests --module spice_lite.tests.test_lastn_query_count\"}}' | node agents/tool-guard.mjs bash-allow 'cd {bench}' 'bench --site test.localhost doctor' 'node .claude/skills/performance-review/scripts/** ...' 'git log'; echo $?", "expected": "stderr `tool-guard [sre] blocked Bash: \"bench --site test.localhost run-tests --module spice_lite.tests.test_lastn_query_count\" is outside this agent's Bash allowlist ...`, exit 2"},
